// The OS graph core (rust/os-graph) running as WebAssembly inside the page.
//
// The page is a file:// document in a macOS WKWebView (or a Tauri WebView2 on Windows), loaded
// as one classic script, so it cannot fetch a .wasm file. The bytes are embedded (bytes.ts,
// generated by scripts/build-os-wasm.sh).
//
// Two ways in:
//   - initOsGraphAsync(): compiles with WebAssembly.compile, then instantiates the compiled
//     module. Chromium refuses synchronous compiles of more than 4 KB on the main thread, so
//     the page uses this path. Idempotent: every caller shares one in-flight promise.
//   - initOsGraph(): the synchronous path (initSync on the bytes). Kept for node and WebKit,
//     and as the fallback for a caller that cannot wait.
//
// The glue in pkg/ is the wasm-bindgen output for --target web with no default module path
// and --experimental-reset-state-function. A panic in the core aborts (panic = "abort"), which
// traps as a WebAssembly.RuntimeError and leaves the instance damaged; runCore() resets the
// glue (re-instantiating from the same compiled module) and rethrows a plain Error.
//
// The core speaks JSON. These wrappers serialise the inputs, parse the output and turn the
// `{ "error": ... }` object the core returns on bad input into a thrown Error.
import {
  initSync,
  build_system_graph_json,
  orbit_layout_json,
  __wbg_reset_state,
} from './pkg/graph_kit_os.js';
import { OS_GRAPH_WASM_BASE64 } from './bytes';
import type { CGData } from '../../../typescript/src/models';
import type {
  BuildOptions,
  OrbitLayout,
  OrbitOptions,
  OsSnapshot,
  SystemGraph,
  Vec3,
} from '../../../typescript/src/system/types';

type Base64Decoder = { from(data: string, encoding: 'base64'): Uint8Array<ArrayBuffer> };

/** Bytes of the embedded module. `atob` is used in the page; `Buffer` covers node (tests). */
function decodeBase64(b64: string): Uint8Array<ArrayBuffer> {
  if (typeof atob === 'function') {
    const binary = atob(b64);
    const bytes = new Uint8Array(new ArrayBuffer(binary.length));
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    return bytes;
  }
  const buffer = (globalThis as { Buffer?: Base64Decoder }).Buffer;
  if (!buffer) throw new Error('OS graph core: no base64 decoder (atob or Buffer) is available');
  return buffer.from(b64, 'base64') as Uint8Array<ArrayBuffer>;
}

/** Where the core stands. 'idle': nothing has started it yet. */
export type OsGraphStatus = 'idle' | 'loading' | 'ready' | 'failed';

let status: OsGraphStatus = 'idle';
let inflight: Promise<void> | null = null;

/** The core's state: 'loading' while initOsGraphAsync is compiling. */
export function osGraphStatus(): OsGraphStatus {
  return status;
}

/** True once the core is instantiated. Idempotent: later calls are no-ops. */
export function osGraphReady(): boolean {
  return status === 'ready';
}

/**
 * Instantiates the core synchronously (node, WebKit, or a caller that cannot wait). Later
 * calls are no-ops. Throws where the engine refuses a synchronous compile (Chromium's main
 * thread, above 4 KB); the page then sees the failure through its draw.
 */
export function initOsGraph(): void {
  if (status === 'ready') return;
  initSync({ module: decodeBase64(OS_GRAPH_WASM_BASE64) });
  status = 'ready';
}

/**
 * Compiles the core off the synchronous path and instantiates it. Resolves when the core is
 * ready; rejects (and sets status 'failed') when the compile fails. Idempotent: every call
 * returns the same promise until it settles, and a ready core resolves at once. A host
 * should call this on mount; the page's loading state covers the wait.
 */
export function initOsGraphAsync(): Promise<void> {
  if (status === 'ready') return Promise.resolve();
  if (inflight) return inflight;
  status = 'loading';
  inflight = (async () => {
    try {
      const module = await WebAssembly.compile(decodeBase64(OS_GRAPH_WASM_BASE64));
      // A synchronous init that finished while we compiled wins; instantiate only once.
      if (osGraphStatus() !== 'ready') {
        initSync({ module });
        status = 'ready';
      }
    } catch (err) {
      status = 'failed';
      throw err;
    } finally {
      inflight = null;
    }
  })();
  return inflight;
}

/**
 * Runs one call into the core. A WebAssembly.RuntimeError is a trap: the core panicked (or
 * ran out of bounds) and the instance is damaged. The glue is reset, which re-instantiates
 * the core from its compiled module, and the caller gets a plain Error with the trap as its
 * cause. The next call runs on the fresh instance.
 */
export function runCore<T>(call: () => T): T {
  try {
    return call();
  } catch (err) {
    if (err instanceof WebAssembly.RuntimeError) {
      __wbg_reset_state();
      const crashed = new Error('OS graph core crashed; it was restarted');
      (crashed as Error & { cause?: unknown }).cause = err;
      throw crashed;
    }
    throw err;
  }
}

/**
 * Parses a core response and throws when it is the `{ "error": "..." }` object the core
 * builds (api.rs: exactly one key, a string). Any other object is a result, even one that
 * happens to have an `error` key.
 */
export function parseResult(json: string, what: string): unknown {
  const value = JSON.parse(json) as unknown;
  if (value !== null && typeof value === 'object' && !Array.isArray(value)) {
    const keys = Object.keys(value);
    const error = (value as { error?: unknown }).error;
    if (keys.length === 1 && keys[0] === 'error' && typeof error === 'string') {
      throw new Error(`${what}: ${error}`);
    }
  }
  return value;
}

/** The system graph for a snapshot and/or a project (either may be null). */
export function buildSystemGraph(
  snapshot: OsSnapshot | null,
  project: CGData | null,
  opts: BuildOptions = {},
): SystemGraph {
  initOsGraph();
  const json = runCore(() =>
    build_system_graph_json(
      JSON.stringify(snapshot ?? null),
      JSON.stringify(project ?? null),
      JSON.stringify(opts ?? null),
    ),
  );
  return parseResult(json, 'buildSystemGraph') as SystemGraph;
}

type WireLayout = {
  core: [string, Vec3][];
  ring: [string, Vec3][];
  communityCenters: Vec3[];
  bounds: { radius: number };
};

/** The 3D layout of a system graph. Maps are keyed by id, in the order the core gives them. */
export function orbitLayout(graph: SystemGraph, opts: OrbitOptions = {}): OrbitLayout {
  initOsGraph();
  const json = runCore(() => orbit_layout_json(JSON.stringify(graph), JSON.stringify(opts ?? null)));
  const wire = parseResult(json, 'orbitLayout') as WireLayout;
  return {
    core: new Map(wire.core),
    ring: new Map(wire.ring),
    communityCenters: wire.communityCenters,
    bounds: wire.bounds,
  };
}
